// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes: module, agent tool and text diffs"
// Changes: get_draft_changes at the MCP message level – an agent reads what adopting its draft would do to the
//          current project, in the changes module's shape, with the "changed on both sides" flags.

import { describe, expect, it } from 'vitest'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { agentHarness } from './agentTestHarness'

const h = agentHarness()
const { call, rpc } = h

// E → id | id + E has an LL(1) conflict in cell [E, id].
const expressions = (): ProjectData => ({
  ...defaultProjectData(),
  def: { nonterminals: 'E\nR', terminals: 'id +', start: 'E' },
  ll: { grammar: 'E -> id\nE -> id + E', input: 'id + id' },
  prec: { terminals: ['+', 'id'], cells: { 'id\u0001+': '>' }, rules: 'E -> E + E\nE -> id', input: 'id' },
  names: { map: 'id ID', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
})

async function newDraft() {
  const project = h.store.createProject('Výrazy', expressions())
  const { draft } = await call('create_draft', { project: project.id, label: 'Oprava konfliktu' })
  return { project, draft, target: { kind: 'draft', id: draft.id } }
}

describe('get_draft_changes', () => {
  it('is a read-only tool offered with the read tools', async () => {
    const { result } = await rpc('tools/list')
    const tool = (result.tools as { name: string; annotations: any; inputSchema: any }[]).find((t) => t.name === 'get_draft_changes')
    expect(tool?.annotations.readOnlyHint).toBe(true)
    expect(tool?.inputSchema.required).toEqual(['draft'])
  })

  it("an agent sees what adopting its draft would do: the grammar rules diff, the resolved conflict, the sets", async () => {
    const { project, draft, target } = await newDraft()
    await call('set_grammar_rules', { target, text: 'E -> id R\nR -> + E\nR -> eps' })
    await call('set_relation', { target, stack: '+', input: 'id', relation: '<' })

    const res = await call('get_draft_changes', { draft: draft.id })
    expect(res.target).toMatchObject({ kind: 'draft', id: draft.id, revision: 3 })
    expect(res.project).toEqual({ id: project.id, revision: project.revision })
    const { changes } = res
    expect(changes.grammarRules.changed).toBe(true)
    expect(changes.grammarRules.lines.map((l: { kind: string; text: string }) => `${l.kind} ${l.text}`)).toEqual([
      'removed E -> id',
      'removed E -> id + E',
      'added E -> id R',
      'added R -> + E',
      'added R -> eps',
    ])
    expect(changes.precTable).toMatchObject({ changed: true, cells: [{ stack: '+', input: 'id', old: '', new: '<' }] })
    expect(changes.llTable.resolvedConflicts).toEqual([
      { nonterminal: 'E', terminal: 'id', rules: [{ rule: 1, text: 'E → id' }, { rule: 2, text: 'E → id + E' }] },
    ])
    expect(changes.llTable.newConflicts).toEqual([])
    expect(changes.sets.nonterminals.map((n: { nonterminal: string }) => n.nonterminal)).toEqual(['R'])
    expect(changes.definition.changed).toBe(false)
    expect(changes.reductionRules).toMatchObject({ changed: false, changedOnBothSides: false })
  })

  it('is measured against the current project and flags parts the human also changed there', async () => {
    const { project, draft, target } = await newDraft()
    await call('set_reduction_rules', { target, text: 'E -> E + E\nE -> ( E )\nE -> id' })
    // Meanwhile the human edits the reduction rules and the grammar rules of the project.
    const saved = h.store.saveProject(
      project.id,
      { ...project.data, ll: { ...project.data.ll, grammar: 'E -> id' }, prec: { ...project.data.prec, rules: 'E -> id' } },
      project.revision,
    )
    expect(saved.status).toBe('saved')

    const { changes, project: measured } = await call('get_draft_changes', { draft: draft.id })
    expect(measured.revision).toBe(project.revision + 1)
    expect(changes.reductionRules).toMatchObject({ changed: true, changedOnBothSides: true })
    // Changed only in the project: adopting the draft's grammar rules would bring back the old text.
    expect(changes.grammarRules).toMatchObject({ changed: true, changedOnBothSides: false })
    expect(changes.precTable).toMatchObject({ changed: false, changedOnBothSides: false })
  })

  it('an unknown draft is a clear error', async () => {
    expect(await call('get_draft_changes', { draft: 'nope' })).toEqual({
      error: 'No draft with id "nope". Use list_drafts on a project to find draft ids.',
    })
  })
})
